import{_ as l,a0 as i,w as d,s as m,ao as a,I as t,a1 as n,A as p,x as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在瀏覽器中啓用深色模式 | LCTT x X-CMD","titleTemplate":false,"description":"如何在瀏覽器中啓用深色模式 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在瀏覽器中啓用深色模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在瀏覽器中啓用深色模式 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220904 How to Enable Dark Mode in Web Browser","title":"如何在瀏覽器中啓用深色模式","tag":"202209","desc":""},"relativePath":"202209/20220904 How to Enable Dark Mode in Web Browser.md","filePath":"[post].md"}'),s={name:"202209/20220904 How to Enable Dark Mode in Web Browser.md"};function u(b,e,h,f,g,w){const o=i("Link");return d(),m("div",null,[e[22]||(e[22]=a('<h1 id="如何在瀏覽器中啓用深色模式" tabindex="-1">如何在瀏覽器中啓用深色模式 <a class="header-anchor" href="#如何在瀏覽器中啓用深色模式" aria-label="Permalink to “如何在瀏覽器中啓用深色模式”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/15/232124u1ikykxri6oehx0h.jpg" alt=""></p><blockquote><p>本指南旨在幫助你瞭解如何在流行的瀏覽器，如 Firefox、谷歌 Chrome、Chromium 和微軟 Edge 中啓用深色模式。</p></blockquote><p>我們都喜歡深色模式。許多人喜歡它，而不是標準的淺色模式。雖然許多桌面應用提供了原生的深色模式，但一些應用通過桌面環境的基礎模式適應深色模式。</p><p>你不能否認，我們都在瀏覽器上花了好多時間。我們很少使用桌面應用（除非你是在工作，如視頻編輯等）。因此，當你在瀏覽器上花很多時間閲讀和學習時，你應該也可以選擇深色模式。但是，對於各個瀏覽器，稍微有點不同。</p><p>本指南為你提供簡單的步驟，你可以按照這些步驟在 Mozilla Firefox、Chromium、Chrome 和 Edge 瀏覽器中啓用深色模式。</p><h3 id="在瀏覽器中啓用深色模式" tabindex="-1">在瀏覽器中啓用深色模式 <a class="header-anchor" href="#在瀏覽器中啓用深色模式" aria-label="Permalink to “在瀏覽器中啓用深色模式”">​</a></h3><h4 id="在-firefox-中啓用深色模式" tabindex="-1">在 Firefox 中啓用深色模式 <a class="header-anchor" href="#在-firefox-中啓用深色模式" aria-label="Permalink to “在 Firefox 中啓用深色模式”">​</a></h4><p>打開 Firefox ，點擊右上角的設置菜單。</p><p>點擊 “<ruby>設置<rt>Settings</rt></ruby> &gt; <ruby>擴展和主題<rt>Extension and Themes</rt></ruby>”。</p><p>選擇“<ruby>深色主題<rt>Dark Theme</rt></ruby>”並點擊“<ruby>啓用<rt>enable</rt></ruby>”。然後你應該看到深色模式被應用到 Firefox。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Enable-dark-mode-in-Firefox.jpg" alt="Enable dark mode in Firefox"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Firefox-in-Dark-Mode-1024x423.jpg" alt="Firefox in Dark Mode"></p><p>要恢復它，按照同樣的步驟，選擇淺色主題。</p><h4 id="chromium-和-chrome-的深色模式" tabindex="-1">Chromium 和 Chrome 的深色模式 <a class="header-anchor" href="#chromium-和-chrome-的深色模式" aria-label="Permalink to “Chromium 和 Chrome 的深色模式”">​</a></h4><p>Chromium 或 Chrome 默認不預裝任何深色主題。因此，你需要去 Chrome 商店，下載任何你想要的深色主題。在本指南中，我將推薦 “Morpheon Dark” 主題，它有超過一百萬用户在使用它。</p><p>從 Chromium 瀏覽器中打開 Morpheon Dark 主題頁面（從以下鏈接）。</p>',17)),t("blockquote",null,[t("p",null,[t("strong",null,[n(o,{href:"https://chrome.google.com/webstore/detail/morpheon-dark/mafbdhjdkjnoafhfelkjpchpaepjknad?hl=en-GB"},{default:p(()=>[...e[0]||(e[0]=[r("Chrome 網絡商店中的 Morpheon Dark 主題",-1)])]),_:1})])])]),e[23]||(e[23]=t("p",null,[r("點擊“"),t("ruby",null,[r("添加到 Chrome"),t("rt",null,"Add To Chrome")]),r("” 按鈕。它應該會在 Chrome 中啓用。")],-1)),t("p",null,[e[2]||(e[2]=r("你可能想探索 Chrome 網絡商店中的其他黑白或深色主題。",-1)),n(o,{href:"https://chrome.google.com/webstore/category/collection/dark_themes"},{default:p(()=>[...e[1]||(e[1]=[r("請訪問此頁面，查看所有的深色主題集合",-1)])]),_:1}),e[3]||(e[3]=r(" 。",-1))]),e[24]||(e[24]=t("p",null,"然而，你應該記住一件事：這個主題不會改變設置或上下文菜單。這很明顯。因為它只是改變了瀏覽器窗口，而那些菜單是操作系統本身的一部分（有時）。",-1)),e[25]||(e[25]=t("p",null,[t("img",{src:"https://www.debugpoint.com/wp-content/uploads/2021/10/Chromium-Dark-Theme-1024x463.jpg",alt:"Chromium Dark Theme"})],-1)),e[26]||(e[26]=t("p",null,"對 Google Chrome 也要按照同樣的步驟進行。",-1)),e[27]||(e[27]=t("h4",{id:"edge-瀏覽器的深色模式",tabindex:"-1"},[r("Edge 瀏覽器的深色模式 "),t("a",{class:"header-anchor",href:"#edge-瀏覽器的深色模式","aria-label":"Permalink to “Edge 瀏覽器的深色模式”"},"​")],-1)),t("p",null,[e[5]||(e[5]=r("然而，",-1)),n(o,{href:"https://www.debugpoint.com/2020/10/how-to-install-edge-ubuntu-linux/"},{default:p(()=>[...e[4]||(e[4]=[r("微軟 Edge 瀏覽器",-1)])]),_:1}),e[6]||(e[6]=r(" 默認帶有更好的深色主題。它允許你從設置中使用 GTK+、淺色和深色模式。",-1))]),e[28]||(e[28]=a('<p>打開 Edge 瀏覽器</p><p>點擊右上角的三個小圓點。</p><p>進入“<ruby>外觀<rt>Appearance</rt></ruby>”，選擇“<ruby>深色<rt>Dark</rt></ruby>”。這就完成了。</p><p>這個 Edge 的深色主題實現得更好，因為它改變了上下文菜單和地址欄。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Edge-in-Dark-Theme-1024x541.jpg" alt="Edge in Dark Theme"></p><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>如果你是一個高級用户，你可能不需要這個指南。你可以搞清楚。</p><p>但我們為所有的讀者涵蓋了所有從基礎到高級的教程。許多新的 Linux 用户可能也不知道如何在瀏覽器中啓用深色模式。</p><p>因此，話雖如此，我希望這能幫助你和其他人。如果你遇到任何麻煩，請在下面的評論欄裏告訴我。</p><hr>',10)),t("p",null,[e[8]||(e[8]=r("via: ",-1)),n(o,{href:"https://www.debugpoint.com/dark-mode-browser/"},{default:p(()=>[...e[7]||(e[7]=[r("https://www.debugpoint.com/dark-mode-browser/",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=r("作者：",-1)),n(o,{href:"https://www.debugpoint.com/author/admin1/"},{default:p(()=>[...e[9]||(e[9]=[r("Arindam",-1)])]),_:1}),e[14]||(e[14]=r(" 選題：",-1)),n(o,{href:"https://github.com/lkxed"},{default:p(()=>[...e[10]||(e[10]=[r("lkxed",-1)])]),_:1}),e[15]||(e[15]=r(" 譯者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:p(()=>[...e[11]||(e[11]=[r("geekpi",-1)])]),_:1}),e[16]||(e[16]=r(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:p(()=>[...e[12]||(e[12]=[r("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=r("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[17]||(e[17]=[r("LCTT",-1)])]),_:1}),e[20]||(e[20]=r(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:p(()=>[...e[18]||(e[18]=[r("Linux中國",-1)])]),_:1}),e[21]||(e[21]=r(" 榮譽推出",-1))])])}const T=l(s,[["render",u]]);export{C as __pageData,T as default};
